import{_ as t,c as l,o,j as a,a as n}from"./chunks/framework.B1wcI2Dt.js";const m=JSON.parse('{"title":"关于我","description":"","frontmatter":{"layout":"doc","editLink":false,"lastUpdated":false,"isNoBackBtn":true},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),r={name:"about.md"};function s(d,e,p,c,i,u){return o(),l("div",null,e[0]||(e[0]=[a("h1",{id:"关于我",tabindex:"-1"},[n("关于我 "),a("a",{class:"header-anchor",href:"#关于我","aria-label":'Permalink to "关于我"'},"​")],-1),a("p",null,"我的故事应该从哪里开始说起呢？",-1),a("p",null,"每次说到我的小时候，我的家里人总是和我说，我小时候半只脚踏进了鬼门关，我问为什么，嗷，貌似原来是那时候突发急性肠道炎，乡镇县里的医院都不能治，最后去市里的医院才治好了，原来那时候我就离死亡那么近了呀，我的母亲没有吃过什么好吃的，所以怀孕到我生产出来都是瘦瘦小小的，刚出生好像只有4斤，嘿嘿嘿，我可真命大呀。",-1),a("p",null,"不过有时候确实会希望自己为什么还活着，没次看到当父母没有生我，就可以省下一大笔钱这种视频，我每次都受不了，我的记忆是不快乐的，快乐是什么，我并不知道，从读书到现在，我的快乐到底在哪里。小学的时候，一、二年级都有我的妈妈接送我上小学，没有什么特别的记忆，哦对了，那时候放学路上还会摘一些野菜吃呢，哈哈哈，我觉得好有意思，吃那种酸酸的草，还有野菜，我的妈妈小时候没有东西吃的时候是不是就只能吃这些了，到了三年级之后，我慢慢长大了，每天都是由我自己走路去上下学，那时候有一个手抄报类似的手工作业，我精心的准备了作品，交给了老师，并获得了小奖，一本本子，但是因为拿本子的时候被同桌挤着没有那么快，老师就说：“快点呀，磨磨唧唧的，怎么跟娘炮一样”，从此“娘炮”跟了我好久，他们总是以这种词语欺负我，我就拼命的告老师，老师看到是那些交钱补课的同学，默不作声。那些同学看到我告老师，变本加厉的对我欺凌，被堵厕所用拖把泼脏水，被在放学路上殴打，被用皮筋枪打，被各种各样的欺凌，因为放学路上总是有一些工地的架子的竹子或者其他的，我们家没有热水器，那时候还要妈妈烧水，我还抗过好多竹子回家呢，后来我发现家里的钱在一个好看的衣服袋子里，红红的钞票，邪恶的信念占据了我的脑子，偷偷的拿了200元，我用这两百元买了好多好多用的，吃的，还抽奖，然后分发给班上的同学，那样他们就愿意和我玩了，就不再欺负我了，200好快就花掉了，于是我又偷偷的拿了几百元放到了文具盒中，这一次就没有那么幸运啦，妈妈爸爸在整理书包的时候，打开了文具盒，发现了这些钱，于是睡梦中的我被叫起来询问，我……偷了钱……于是少不了衣架的鞭打，好疼，我到处跑，跑的他们找不到……我小时候就是被这样子打回来的，我不是没有告诉过我爸爸妈妈校园欺凌，不是没有告诉过老师，可结果就是告诉你，你打回去，可他们人好多啊，我打不过，我又怕告诉我爸爸又让他说，你怎么这么没有用，所以我从来没有告诉过他，哦，对了，在4年级还是5年级的时候，去乡下看望爷爷奶奶，突然间被时速飞快的出租车撞飞啦，哈哈哈哈，那时候居然只是青一块紫一块，但是由于请假感觉脑子被撞坏掉了，英语之前明明随便考70多的，居然只有不及格了，之后的英语就没有及格咯。还有还有，在4年级还是5年级，我们班突然来了一个非常高，但是有智力缺陷的人，是个大孩子了，但是他什么话都不听，妥妥的神经病一样的，他就应该去特殊学校啊，为什么安排到了我们学校，我们班。搞不懂，那时候我已经是班上被排挤的啦，所以被分配的位置也是最后，他因为高也是最后，记得有一次，他不知道因为什么原因突然发病，用力把我的头撞到墙上，好痛……老师也拿他没有办法，说了几句就算了，唉，那时候又怕老师，又怕同学，又怕爸爸妈妈，谁都不敢说。经常被老师打，上黑板做不出来算数题目被踹倒，然后又罚站罚抄。被拎耳朵拎出油状液体，还会结块，掏都掏不干净。我的小学……",-1),a("p",null,"到了初中，更是惨的不要不要的，打的更狠啦，嘿嘿嘿，到了初中又是老生常谈都校园欺凌，感觉和小学拿的剧本一样，又让我发现了爸爸妈妈放钱的地方，不过那时候再没有拿那么多了，不过后面有一个同学向我借钱，我居然借了，找他还，就是过几天，几个月，结果，读了一个学期转走了，哈哈哈哈，我好心好意偷出来的钱就这么没有了。还有还有那时候班主任老师特别狠，打人老疼了，一下青两下紫，我不知道怎么说这种教育方式，但是我真的很讨厌，另外印象深刻的就是有一次和同学音乐课上开玩笑，然后音乐老师觉得我们不听话当众打了我和另外一个同学的脸一巴掌。不疼但是很丢脸。然后那同学就把这个事情告诉了他的爸爸，他的爸爸就和班主任说，班主任就把我和他叫到了办公室，和那老师，老师说我又没有打的很重，就说这样子打的，说完就有打了我的脸一巴掌，然后两个老师有说有笑的说，下次不要打脸了，然后又把问题丢了我，说我不好好上课干嘛去招惹他，说我拿这他打断的尺子又狠狠的打了我的手……还有还有，那时候在走廊嬉戏打闹，我们班一个女同学路过，我的手好像碰到了他的胸，然后就在那放狠话，我根本不知道怎么回事，然后过了一天晚上被叫到了小树林打了，哈哈哈哈，我就是这样子被各种殴打，然后老师看我好欺负，又给我安排各种活，同学眼里的狗腿子，老师眼里的差学生……我该怎么办，我也尝试过一些事情，但是一次也没有成功。",-1),a("p",null,"我不知道朋友是什么，所以我无比渴望拥有朋友，甚至偷家里的钱去让那些人和我玩，我真的希望有自己的朋友。我爱我的高中，至少爱我的高一和高二……高三就算了吧，算了的原因不是试卷多，不是其他的，只是换班主任了，那个班主任差点让我死。在高一的时候我遇到了很好很好的老师，会给学生分享好吃的，会关心学生，更会托举学生让他们尽可能的变的更亮，我也遇到了一个让我无法忘怀的人，那时候发书本，我们老师叫我去帮忙发书，我从原来的6本书，这个老师有事，那领导有事情，到最后的13本书，那位是最后一个6班，那时候放学了，我怕晚自习赶不上，就非常急，他看出我很急，就想帮忙，结果我在剪绳子的时候不小心剪到了他的大拇指，那时候流了好多血，我很惊慌，觉得完了又要赔钱了要被爸爸妈妈骂了，结果他一直说没事的没事的。后续打破伤风什么的从来没有找过我，我……倍感惭愧，高一下学期我们在一个班了。然后到了高二，他好像有点谈恋爱了，我抑郁了，我那时候不知道gay是什么，我只知道自己好像要失去一个朋友了，失去一个来之不易的朋友了，我想挽留，所以用自残的方式挽留，那些时候我的手臂上全是划痕，那时候是夏天，短袖我不怕看到，就是想让他注意，我不想失去朋友，我太懂那种绝望感觉了，在小学，在初中，没有见过光，我以为我的世界是黑暗的，你成为一束光照进我世界的时候我再也接受不了黑暗了，拼命的挽留……那时候我的妈妈又生了大病，在县城医院住院，住了几天查了好多东西，没有任何用，然后又去市里医院住院，那时候家里就我一个人，再加上这个事情，我不知道该怎么去面对了，天天朝天怒吼，看苍穹惊雷，淋雨回家，慢慢的，另一个同学闯进了我的内心，我又开始诉说……虽然没有解决伤痛，但是缓解了大部分的问题，在高中，我遇到了好多好多人，每一个都有不一样的故事，每一个都很精彩，没有了校园欺凌，虽然我发生了极端行为，但不可否认，他是我人生到现在唯一怀念的时光，我无比怀念我的高中，就算他人我伤痕累累，那也是我自作自受。",-1),a("p",null,"到了现在的大学，我又改怎么说呢，在高中的暑假，我经历了兵检，经历了到大学前一个星期才确定上学，交了学费。那时候由父母送我到了繁华的南昌，又匆匆的离别，我慢上不舍，这是我第一次离家，我看着他们远去，看到了姐姐给我发的红包，我励志要好好学习，在大一的时候经历了军训，走了走南昌的大街小巷，去了好多好多地方，也遇到了形形色色都同学，还吃了好多好多好吃的。那时候和爸妈打电话每次都哭，说实话想家了，所以那时候每个月都会回家，到了大一下学期，完啦，抑郁的我出现了，才一个月，我依然会发牢骚，去寻求解救的办法，可这一次让我知道了，真实的自己要像粽子一样包裹，不能给任何人看，至少不能让身边人知道，我就是与身边人说了抑郁的行为，他转头就告诉了辅导员，那一天是我至今最难受的一天，那一天被关在了秘密的办公室，不让我走，面对所有老师轮番进攻，并告诉我要叫我的家长来接我回家，我真的崩溃了，那种窒息的崩溃感让我想要死亡，那一天晚上的12点，我颤抖的下了楼梯，看到了爸爸，我痛哭，内心在想，家里没有车，你每天9点多都睡觉了，现在她这样子吵起来，然后又四处求人叫车，天啊，我到底做了什么，那时候你还在养伤，手指骨头被压断，为什么，为什么要发生这种事情，回到家，我一晚上没有睡觉，第二天，我想复学，不想让你们担心，结果你们打电话和辅导员说我挺好的，可以复学了，他居然让你们看看我的手臂，那一条条伤疤，为什么，为什么你要这样子逼我，我绝望了……然后你又告诉父母要去医院开证明才可以复学，又辗转医院，花了好多好多钱，我努力的装做没有生病，医生问我做过几次这种行为，我就说这一次，显然，这很有效果，证明拿到了，结果他又要家长去学校，你们又陪同我去了学校，我被带到了心理诊疗室，学校的老师对我进行了探查，家长择被带到了办公室，最后我们相见，你签了一份无责，内容大概是我出事情了，与学校无关系，这样子才让我最终复学成功。我恨自己，为什么不能藏住自己，我恨……到了大二，那时候因为我们宿舍少人，辅导员安排了其他人来我们宿舍，第一个来了2天就自己走了，第二个是一个有疾病复学的，住了一个月，我也有点受不了，天天不想上课又说一些颜色的话，让我觉得不好。最后又来了一个被别人排挤出来的来了我们宿舍，噩梦降临了，来的第一天居然就说，你们觉得我有什么不好的可以直接说，甚至骂我都没有关系的，天啊，正常人怎么第一次就这样子说啊。我们受不了他的不讲卫生，天天垃圾不丢，天天在厕所抽烟，各种各样的坏习惯，不想上课就请假，天天在宿舍吹空调，我不明白这样子混的人为什么要来学校，还各种吹牛，我真的搞不懂，原来是有一个政府里干活的爸。唉，和他住了两个多月我们就各种吵，各种说他，他也从来不听，有一次去厕所，厕所有一个虫子，出来就叫，为什么厕所有虫子，啊？？？！是人类嘛，就算是家里的厕所因为一些原因也会有虫子吧，然后还问我们为什么不扫掉，天啊，我的室友就问他，你看见了为什么不扫，他回复了一句，我以为你们要做实验，天啊。什么人啊，各种各样的事情人我们整个宿舍都非常无语。然后，我们大三了，又要换宿舍了，宿舍钥匙给到了我，每个人一把，我就给他们了，结果好死不死的，他那把是一把没有用的钥匙，我拿到的时候我哪知道啊，他上面还有标签。后面我就说你不行就拿钥匙去配一把。结果他说他过几天要走，不来了，哇，那时候我们普天同庆，终于要走了，太高兴了，我甚至买了两杯奶茶请室友喝，结果，下个学期他又回来了，天，这简直是噩梦，回来的第一件事就是说钥匙，我说我都说了叫你去配一把，他装做不知道，笑死了，然后还叫他的朋友上门挑衅我，我以因为好多原因就是老实懦弱的，不过这个机会看清楚了室友，原来是那样子的人，一有事情就把自己撇干净，哈哈哈哈，我以为2年会有一丢丢的感情，至少我帮助了他们好多好多，原来是我自作多情了啊。我那晚上哭了，我是一个泪点很低的人，总是会随随便便流眼泪，看云边有个小卖部的时候，看到外婆走了，我哭了，哭的是因为，我的母亲出生就没有妈妈，我也没有外婆的疼爱，外婆啊，你在天上看到妈妈受这么多哭，你不会难受嘛。我会看到很多泪点哭泣，想死时总有一个文案，说，你从高楼跳下，你的母亲抱着你的尸体痛哭，你连为她擦眼泪的机会都没有了。我的人生……真的好失败啊。",-1)]))}const _=t(r,[["render",s]]);export{m as __pageData,_ as default};
